// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.LinkedHashSet;
import java.util.Set;

import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.GenericPlanNode;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailTupleQuery;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * The same OPTIONAL replay contract as {@link LmdbNativeOptionalScanReplayStoreTest}, served by the Janino-compiled
 * kernel (synchronous compile, zero threshold) instead of the interpreter. The inherited tests prove result parity and
 * probe counts; the extra test proves the compiled tier is the one that executed.
 */
public class LmdbNativeOptionalScanReplayCompiledTest extends LmdbNativeOptionalScanReplayStoreTest {

	private static final String[] COMPILED_PROPERTIES = { "rdf4j.lmdb.janinoCodegen.synchronous",
			"rdf4j.lmdb.janinoCodegen.thresholdRows" };
	private final java.util.Map<String, String> savedCompiled = new java.util.HashMap<>();

	@Override
	protected void configureTier() {
		for (String property : COMPILED_PROPERTIES) {
			savedCompiled.put(property, System.getProperty(property));
		}
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
	}

	@Override
	protected String forcedStrategy() {
		return "irKernel";
	}

	/**
	 * Runs before the inherited {@code tearDown}. It must not override that method: a JUnit 5 lifecycle method that is
	 * overridden without its own annotation is silently skipped, which would leak every system property and the open
	 * repository into later test classes of the same JVM.
	 */
	@AfterEach
	public void restoreCompiledTier() {
		savedCompiled.forEach((key, value) -> {
			if (value == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, value);
			}
		});
		savedCompiled.clear();
	}

	private static final String[] GUARDED = { "rdf4j.lmdb.nativeQueryEngine.enabled",
			"rdf4j.lmdb.irKernel.optionalReplay.enabled", "rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.janinoCodegen.resumable", "rdf4j.lmdb.janinoCodegen.synchronous",
			"rdf4j.lmdb.janinoCodegen.thresholdRows", "rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.parallel.enabled" };
	private static final java.util.Map<String, String> BEFORE_CLASS = new java.util.HashMap<>();

	@BeforeAll
	public static void snapshotSystemProperties() {
		BEFORE_CLASS.clear();
		for (String property : GUARDED) {
			BEFORE_CLASS.put(property, System.getProperty(property));
		}
	}

	/** The whole class must leave the JVM-wide settings exactly as it found them. */
	@AfterAll
	public static void assertSystemPropertiesRestored() {
		for (String property : GUARDED) {
			assertThat(System.getProperty(property)).as("leaked system property %s", property)
					.isEqualTo(BEFORE_CLASS.get(property));
		}
	}

	@Test
	public void chainQueryIsServedByTheCompiledKernel() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(chainQuery());
			query.setForcedLmdbExecutionStrategy(forcedStrategy());
			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			Set<String> paths = new LinkedHashSet<>();
			collect(plan, paths);
			assertThat(paths).as("executed paths: %s", plan).contains("irKernel").doesNotContain("irKernelInterpreted");
		}
	}

	@Test
	public void aggregateOverOptionalChainUsesTheNonStreamingEmissionAndReplays() {
		String query = "PREFIX ex: <http://example.com/>\n"
				+ "SELECT ?l (COUNT(*) AS ?n) WHERE { ?a a ex:A . ?a ex:link ?l\n"
				+ "  OPTIONAL { ?l ex:member ?m . ?m ex:id ?mid OPTIONAL { ?m ex:stage ?s . ?s ex:id ?sid } } }\n"
				+ "GROUP BY ?l";
		java.util.List<org.eclipse.rdf4j.query.BindingSet> reference;
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			reference = org.eclipse.rdf4j.query.QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		} finally {
			System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		}
		assertThat(reference).hasSize(40);
		for (boolean replay : new boolean[] { false, true }) {
			System.setProperty("rdf4j.lmdb.irKernel.optionalReplay.enabled", Boolean.toString(replay));
			try (SailRepositoryConnection connection = repository.getConnection()) {
				SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
				prepared.setForcedLmdbExecutionStrategy("irAggregate");
				assertThat(org.eclipse.rdf4j.query.QueryResults.asList(prepared.evaluate()))
						.containsExactlyInAnyOrderElementsOf(reference);
			}
		}
		long uncached = metric(query, false, "nativeIrScanOpensActual", "irAggregate");
		long cached = metric(query, true, "nativeIrScanOpensActual", "irAggregate");
		assertThat(uncached).isGreaterThan(3_000L);
		assertThat(cached).as("aggregate OPTIONAL arms must replay repeated keys").isLessThan(uncached / 2);
	}

	private static void collect(GenericPlanNode node, Set<String> paths) {
		if (node == null) {
			return;
		}
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			for (String tag : path.split("\\|")) {
				paths.add(tag.trim());
			}
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collect(child, paths));
		}
	}
}
